def normalize_phone(s: str) -> str:
    """Normalize a US phone number to the form (XXX) XXX-XXXX."""
    import re
    match = re.search(r"\d{3}[-.]?\d{3}[-.]?\d{4}"", s)
    if match:
        number = match.group(0).replace("-", "").replace(".", "")
        return f"({number[:3]}) {number[3:6]}-{number[6:]}
    return s

